        const n = this.v[0].copy(pos || a.pos).sub(target).normalize();
        this.disc(false, 1.2, DISC.SPLAT, target, n, 0.3, 1.3, c, 1, { hold: 0.7 });
      } else if (e.action === 'hookImpact' && pos) {
